-- ═══════════════════════════════════════════════════════════════════════════
-- 20261156 — EEMD places: descriptions in all nine languages (+3 factual corrections)
-- ═══════════════════════════════════════════════════════════════════════════
--
-- DATA ONLY: places.description_i18n on the 33 rows 20261155 gave official_visit. No schema,
-- policy or grant change. Every row had en + tr only; this adds ar, ru, el, fr, es, de, fa,
-- translated from the existing en (tr as cross-check). Berke 2026-11-01: keep en/tr, rewrite
-- only what is factually wrong, and list it. Three were, so en + tr change on these:
--   • Salamis Ancient City — "an amphitheatre" → "a Roman theatre" (the theatre is the monument
--     visitors see; the amphitheatre is unexcavated)
--   • Kyrenia Castle — the Kyrenia ship "2,400-year-old" → "2,300-year-old" (sank c. 300 BC)
--   • Dervish Pasha Mansion — "late-18th-century" → "early-19th-century (1807)"
--
-- COMPARE-AND-SET: a row is written only while md5(its en) is still the text these were
-- translated from, so an edit made since aborts the whole file instead of being overwritten.
-- `||` merges keys: the 7 new languages are added, en/tr are kept except on the three above.
-- Re-run: the en md5 no longer matches on the three corrected rows, so the assertion block
-- accepts either the old or the already-written state (it checks the END state, not the count).
-- ═══════════════════════════════════════════════════════════════════════════
SET ROLE postgres;
BEGIN;
SET LOCAL lock_timeout = '5s';

UPDATE public.places p
   SET description_i18n = p.description_i18n || v.add
  FROM (VALUES
  ('bba0d5cb-001a-405f-ab9d-9913d83e10a3'::uuid, 'a324828bd3478fc9666ea0f3dabfaa77', '{"ar": "متحف تذكاري في حي كومسال، أُقيم في المنزل السابق للدكتور نهاد إلهان، حيث قُتلت زوجته وأطفاله الثلاثة في 24 ديسمبر 1963 خلال أعمال العنف بين الطائفتين المعروفة بـ«عيد الميلاد الدامي». توثّق الصور والمتعلقات الشخصية تلك الأحداث، وقد حُفظت إلى حد كبير كما وُجدت.", "ru": "Мемориальный музей в квартале Кумсал, расположенный в бывшем доме доктора Нихата Ильхана, чьи жена и трое детей были убиты здесь 24 декабря 1963 года во время межобщинного насилия, известного как «Кровавое Рождество». Фотографии и личные вещи, сохранённые почти в том виде, в каком их нашли, документируют те события.", "el": "Μουσείο-μνημείο στη συνοικία Κουμσάλ, στεγασμένο στο πρώην σπίτι του γιατρού Νιχάτ Ιλχάν, του οποίου η σύζυγος και τα τρία παιδιά σκοτώθηκαν εδώ στις 24 Δεκεμβρίου 1963, κατά τη διακοινοτική βία που έμεινε γνωστή ως «Ματωμένα Χριστούγεννα». Φωτογραφίες και προσωπικά αντικείμενα, διατηρημένα σχεδόν όπως βρέθηκαν, τεκμηριώνουν τα γεγονότα.", "fr": "Musée mémorial du quartier de Kumsal, installé dans l''ancienne maison du Dr Nihat İlhan, dont l''épouse et les trois enfants y furent tués le 24 décembre 1963, lors des violences intercommunautaires connues sous le nom de « Noël sanglant ». Photographies et effets personnels retracent les événements, conservés pour l''essentiel tels qu''ils ont été découverts.", "es": "Museo conmemorativo en el barrio de Kumsal, instalado en la antigua casa del Dr. Nihat İlhan, cuya esposa y tres hijos fueron asesinados aquí el 24 de diciembre de 1963, durante la violencia intercomunitaria conocida como la Navidad Sangrienta. Fotografías y objetos personales documentan los hechos, conservados prácticamente tal como se encontraron.", "de": "Eine Gedenkstätte im Viertel Kumsal, untergebracht im ehemaligen Wohnhaus von Dr. Nihat İlhan, dessen Frau und drei Kinder hier am 24. Dezember 1963 während der als „Blutige Weihnachten“ bekannten Gewalt zwischen den Volksgruppen getötet wurden. Fotografien und persönliche Gegenstände dokumentieren die Ereignisse und sind weitgehend so erhalten, wie man sie vorfand.", "fa": "موزه‌ای یادبود در محله کومسال، در خانه سابق دکتر نهاد ایلهان، که همسر و سه فرزندش در ۲۴ دسامبر ۱۹۶۳ در جریان خشونت‌های بین‌جامعه‌ای موسوم به «کریسمس خونین» در همین‌جا کشته شدند. عکس‌ها و وسایل شخصی این رویدادها را مستند می‌کنند و تقریباً همان‌گونه که یافت شدند حفظ شده‌اند."}'::jsonb),  -- Museum of Barbarism
  ('af3e1e9d-8563-4087-a00e-58a8905a631c'::uuid, 'f07f596e458640c46b0c32057c7a409b', '{"ar": "قصر عثماني مُرمَّم من أوائل القرن التاسع عشر (1807) في حي عرب أحمد، كان منزلًا لدرويش باشا، ناشر أول صحيفة باللغة التركية في قبرص. وقد تحوّل اليوم إلى متحف إثنوغرافي، وأُثّثت غرفه الموزعة على طابقين لتعرض الحياة المنزلية لعائلة قبرصية تركية ميسورة.", "ru": "Отреставрированный османский особняк начала XIX века (1807) в квартале Арабахмет, некогда дом Дервиша-паши — издателя первой на Кипре газеты на турецком языке. Сегодня здесь этнографический музей: комнаты на двух этажах обставлены так, чтобы показать быт состоятельной турко-киприотской семьи.", "el": "Αναστηλωμένο οθωμανικό αρχοντικό των αρχών του 19ου αιώνα (1807) στη συνοικία Αραπ Αχμέτ, άλλοτε κατοικία του Ντερβίς Πασά, εκδότη της πρώτης τουρκόφωνης εφημερίδας της Κύπρου. Σήμερα λειτουργεί ως λαογραφικό μουσείο, με δωμάτια σε δύο ορόφους επιπλωμένα ώστε να δείχνουν την καθημερινή ζωή μιας εύπορης τουρκοκυπριακής οικογένειας.", "fr": "Demeure ottomane restaurée du début du XIXe siècle (1807), dans le quartier d''Arabahmet, qui fut la résidence de Dervish Pasha, éditeur du premier journal en langue turque de Chypre. Devenue musée ethnographique, elle présente sur deux étages des pièces meublées illustrant la vie domestique d''une famille chypriote turque aisée.", "es": "Mansión otomana restaurada de principios del siglo XIX (1807) en el barrio de Arabahmet, antigua residencia de Dervish Pasha, editor del primer periódico en lengua turca de Chipre. Hoy es un museo etnográfico cuyas estancias, repartidas en dos plantas, están amuebladas para mostrar la vida doméstica de una familia turcochipriota acomodada.", "de": "Ein restauriertes osmanisches Herrenhaus aus dem frühen 19. Jahrhundert (1807) im Viertel Arabahmet, einst Wohnsitz von Dervish Pasha, dem Herausgeber der ersten türkischsprachigen Zeitung Zyperns. Heute ist es ein ethnografisches Museum, dessen Räume auf zwei Etagen das häusliche Leben einer wohlhabenden türkisch-zyprischen Familie zeigen.", "fa": "عمارتی عثمانی و مرمت‌شده از اوایل قرن نوزدهم (۱۸۰۷) در محله عرب‌احمد که زمانی خانه درویش پاشا، ناشر نخستین روزنامه ترکی‌زبان قبرس، بود. این بنا اکنون موزه مردم‌شناسی است و اتاق‌هایش در دو طبقه به‌گونه‌ای مبله شده‌اند که زندگی خانگی یک خانواده مرفه ترک قبرسی را نشان دهند.", "en": "A restored early-19th-century (1807) Ottoman mansion in the Arabahmet quarter, once home to Dervish Pasha, publisher of Cyprus''s first Turkish-language newspaper. Now an ethnography museum, its rooms are furnished to show the domestic life of a well-to-do Turkish Cypriot family across two floors.", "tr": "Arabahmet mahallesinde, 19. yüzyıl başlarına (1807) ait, restore edilmiş bir Osmanlı konağıdır; bir zamanlar Kıbrıs''ın ilk Türkçe gazetesinin sahibi Derviş Paşa''nın eviydi. Bugün etnografya müzesi olan yapının odaları, iki kat boyunca varlıklı bir Kıbrıslı Türk ailesinin ev yaşamını yansıtacak şekilde döşenmiştir."}'::jsonb),  -- Dervish Pasha Mansion
  ('6bcd83da-4b7d-43f1-9629-98ebd2bc6bf2'::uuid, '3c00847adffb3cbe500e1df23ff65974', '{"ar": "أحد المساكن الفرنجية القليلة الباقية من العصور الوسطى في المدينة القديمة، ويعود إلى عهد اللوزينيان. رُمِّم هذا المنزل الحجري وأُثّث ليعكس أصوله الوسيطة واستخدامه العثماني اللاحق معًا، مقدّمًا لمحة نادرة عن العمارة السكنية في قبرص خلال الحقبة الفرنجية.", "ru": "Одна из немногих сохранившихся в старом городе средневековых франкских резиденций, относящаяся к эпохе Лузиньянов. Каменный дом отреставрирован и обставлен так, чтобы отразить и его средневековое происхождение, и позднейшее османское использование, — редкая возможность увидеть жилую архитектуру франкского периода Кипра.", "el": "Μία από τις λίγες σωζόμενες μεσαιωνικές φραγκικές κατοικίες της παλιάς πόλης, που χρονολογείται από την περίοδο των Λουζινιανών. Το πέτρινο σπίτι έχει αναστηλωθεί και επιπλωθεί ώστε να αντανακλά τόσο τη μεσαιωνική του προέλευση όσο και τη μεταγενέστερη οθωμανική του χρήση, προσφέροντας μια σπάνια ματιά στην οικιστική αρχιτεκτονική της φραγκικής εποχής της Κύπρου.", "fr": "L''une des rares demeures franques médiévales subsistant dans la vieille ville, datant de l''époque des Lusignan. Restaurée et meublée pour évoquer à la fois ses origines médiévales et son usage ultérieur à l''époque ottomane, cette maison de pierre offre un aperçu rare de l''architecture domestique de la Chypre franque.", "es": "Una de las pocas residencias francas medievales que se conservan en la ciudad vieja, de la época de los Lusignan. La casa de piedra ha sido restaurada y amueblada para reflejar tanto sus orígenes medievales como su posterior uso otomano, y ofrece una visión excepcional de la arquitectura doméstica de la era franca de Chipre.", "de": "Eines der wenigen erhaltenen mittelalterlichen fränkischen Wohnhäuser der Altstadt, das aus der Lusignan-Zeit stammt. Das Steinhaus wurde restauriert und so eingerichtet, dass es sowohl seine mittelalterlichen Ursprünge als auch die spätere osmanische Nutzung widerspiegelt – ein seltener Einblick in die Wohnarchitektur des fränkischen Zypern.", "fa": "یکی از معدود اقامتگاه‌های فرانکی بازمانده از قرون وسطی در شهر قدیم که به دوره لوزینیان بازمی‌گردد. این خانه سنگی مرمت و به‌گونه‌ای مبله شده که هم ریشه‌های قرون وسطایی و هم کاربری بعدی عثمانی آن را بازتاب دهد و نگاهی کم‌یاب به معماری مسکونی دوران فرانکی قبرس ارائه می‌کند."}'::jsonb),  -- Lusignan House
  ('e4b80e27-45fc-47e1-85d5-97da373cfd11'::uuid, '3717e0c4c9a8228d3b704588b744ecb4', '{"ar": "تكية سابقة للطريقة المولوية الصوفية (الدراويش الدوّارون) تعود إلى القرن السابع عشر، وتقع مباشرة داخل بوابة كيرينيا. كانت يومًا مركز الطريقة الرئيسي في الجزيرة، وتعرض اليوم مقتنيات عن حياة الدراويش إلى جانب أضرحة شيوخها وفناء يضم شواهد قبور عثمانية منحوتة.", "ru": "Бывшая обитель суфийского ордена Мевлеви («кружащихся дервишей») XVII века, расположенная сразу за Киренийскими воротами. Некогда главное место собраний ордена на острове, сегодня она представляет экспозицию о жизни дервишей, а также гробницы её шейхов и двор с резными османскими надгробиями.", "el": "Πρώην τεκές του σουφικού τάγματος των Μεβλεβί (των «στροβιλιζόμενων δερβίσηδων») του 17ου αιώνα, ακριβώς μέσα από την Πύλη της Κερύνειας. Άλλοτε κεντρικός τόπος συνάθροισης του τάγματος στο νησί, σήμερα φιλοξενεί εκθέματα για τη ζωή των δερβίσηδων, μαζί με τους τάφους των σεΐχηδών του και μια αυλή με σκαλιστές οθωμανικές επιτύμβιες στήλες.", "fr": "Ancien couvent du XVIIe siècle de l''ordre soufi des Mevlevi (les derviches tourneurs), situé juste après la porte de Kyrenia. Jadis principal lieu de réunion de l''ordre sur l''île, il présente aujourd''hui des expositions sur la vie des derviches, ainsi que les tombeaux de ses cheikhs et une cour ornée de stèles funéraires ottomanes sculptées.", "es": "Antiguo convento del siglo XVII de la orden sufí Mevlevi (los derviches giróvagos), justo al cruzar la Puerta de Kyrenia. Fue en su día el principal lugar de reunión de la orden en la isla y hoy muestra exposiciones sobre la vida de los derviches, junto a las tumbas de sus jeques y un patio con lápidas otomanas talladas.", "de": "Ein ehemaliges Kloster des Sufi-Ordens der Mevlevi (der „tanzenden Derwische“) aus dem 17. Jahrhundert, direkt hinter dem Kyrenia-Tor. Einst zentraler Versammlungsort des Ordens auf der Insel, zeigt es heute Ausstellungen zum Leben der Derwische, dazu die Gräber seiner Scheichs und einen Hof mit gemeißelten osmanischen Grabsteinen.", "fa": "خانقاه سابق طریقت صوفیانه مولویه (درویشان چرخان) از قرن هفدهم، درست در داخل دروازه کیرنیا. این مکان که زمانی محل اصلی گردهمایی این طریقت در جزیره بود، اکنون نمایشگاهی از زندگی درویشان را در کنار آرامگاه شیوخ آن و حیاطی پر از سنگ‌قبرهای حکاکی‌شده عثمانی عرضه می‌کند."}'::jsonb),  -- Mevlevi Tekke Museum
  ('fe916273-78d3-4280-ae1d-8a72eb5cd09c'::uuid, 'c521af0746a12e025068edb434d6ab29', '{"ar": "متحف يوثّق تاريخ المجتمع القبرصي التركي ومقاومته خلال النزاعات بين الطائفتين من خمسينيات القرن العشرين إلى سبعينياته، ويقع بجوار أسوار مدينة نيقوسيا. تضم معروضاته صورًا ووثائق وأسلحة ومتعلقات شخصية من تلك الحقبة.", "ru": "Музей у городских стен Никосии, рассказывающий об истории и сопротивлении турко-киприотской общины в период межобщинных конфликтов 1950–1970-х годов. В экспозиции — фотографии, документы, оружие и личные вещи того времени.", "el": "Μουσείο δίπλα στα τείχη της Λευκωσίας που τεκμηριώνει την ιστορία και την αντίσταση της τουρκοκυπριακής κοινότητας στις διακοινοτικές συγκρούσεις από τη δεκαετία του 1950 έως τη δεκαετία του 1970. Τα εκθέματα περιλαμβάνουν φωτογραφίες, έγγραφα, όπλα και προσωπικά αντικείμενα της εποχής.", "fr": "Musée retraçant l''histoire et la résistance de la communauté chypriote turque pendant les conflits intercommunautaires des années 1950 à 1970, situé au pied des remparts de Nicosie. Il expose photographies, documents, armes et effets personnels de l''époque.", "es": "Museo que documenta la historia y la resistencia de la comunidad turcochipriota durante los conflictos intercomunitarios de las décadas de 1950 a 1970, situado junto a las murallas de Nicosia. Sus vitrinas incluyen fotografías, documentos, armas y objetos personales de la época.", "de": "Ein Museum an der Stadtmauer von Nicosia, das Geschichte und Widerstand der türkisch-zyprischen Volksgruppe während der Konflikte zwischen den Volksgruppen von den 1950er- bis in die 1970er-Jahre dokumentiert. Gezeigt werden Fotografien, Dokumente, Waffen und persönliche Gegenstände aus dieser Zeit.", "fa": "موزه‌ای که تاریخ و مقاومت جامعه ترک قبرسی را در جریان درگیری‌های بین‌جامعه‌ای دهه ۱۹۵۰ تا ۱۹۷۰ مستند می‌کند و در کنار حصار شهر نیکوزیا قرار دارد. عکس‌ها، اسناد، سلاح‌ها و وسایل شخصی آن دوره از جمله اشیای به نمایش درآمده‌اند."}'::jsonb),  -- National Struggle Museum
  ('5c0d21e5-2f1b-4ea9-8a3d-3c9f67dd7d57'::uuid, 'c6d74abf2d3e3689bffbc7b240c50aa6', '{"ar": "يقع هذا المتحف في مبنى بندقي من القرن الخامس عشر في المدينة القديمة، ويجمع منحوتات حجرية وشعارات نبالة وزخارف نوافذ وقطعًا معمارية أُنقذت من مبانٍ تعود إلى العصور الوسطى في أنحاء نيقوسيا. إنه سجلّ هادئ لفن نحت الحجر القوطي وعصر النهضة في المدينة.", "ru": "Расположенный в венецианском здании XV века в старом городе, этот музей собирает резные каменные детали, гербы, оконные ажурные переплёты и архитектурные фрагменты, спасённые из средневековых построек по всей Никосии. Это тихая летопись готического и ренессансного камнерезного искусства города.", "el": "Στεγασμένο σε ενετικό κτίριο του 15ου αιώνα στην παλιά πόλη, το μουσείο συγκεντρώνει σκαλιστά λίθινα έργα, οικόσημα, διάκοσμο παραθύρων και αρχιτεκτονικά θραύσματα που διασώθηκαν από μεσαιωνικά κτίρια σε όλη τη Λευκωσία. Αποτελεί ένα ήσυχο χρονικό της γοτθικής και αναγεννησιακής λιθοξοΐας της πόλης.", "fr": "Installé dans un bâtiment vénitien du XVe siècle de la vieille ville, ce musée rassemble pierres sculptées, blasons, remplages de fenêtres et fragments architecturaux récupérés sur des édifices médiévaux de toute la ville de Nicosie. Un témoignage paisible de l''art des tailleurs de pierre gothiques et Renaissance de la ville.", "es": "Instalado en un edificio veneciano del siglo XV en la ciudad vieja, este museo reúne cantería tallada, escudos de armas, tracerías de ventanas y fragmentos arquitectónicos rescatados de edificios medievales de toda Nicosia. Es un testimonio sereno de la cantería gótica y renacentista de la ciudad.", "de": "Untergebracht in einem venezianischen Gebäude aus dem 15. Jahrhundert in der Altstadt, vereint dieses Museum Steinmetzarbeiten, Wappen, Fenstermaßwerk und Architekturfragmente, die aus mittelalterlichen Bauten in ganz Nicosia geborgen wurden. Ein stilles Zeugnis der gotischen und Renaissance-Steinmetzkunst der Stadt.", "fa": "این موزه که در بنایی ونیزی از قرن پانزدهم در شهر قدیم جای دارد، سنگ‌تراشی‌ها، نشان‌های خانوادگی، تزئینات پنجره و قطعات معماری نجات‌یافته از بناهای قرون وسطایی سراسر نیکوزیا را گرد آورده است. این مجموعه روایتی آرام از سنگ‌تراشی گوتیک و رنسانس شهر است."}'::jsonb),  -- Lapidary Museum
  ('8a90025d-70ce-4cb4-baa8-31c40a131f44'::uuid, 'e8bd577045b8c4fc3ebd6a3e82e3e090', '{"ar": "منزل تقليدي مُرمَّم سُمّي نسبةً إلى أفاريزه الخشبية البارزة المميزة (ساتشاك)، وهي سمة نموذجية للعمارة السكنية في نيقوسيا القديمة. يُستخدم اليوم مركزًا للفنون والثقافة، ويستضيف معارض وفعاليات في بيئة من العهد العثماني محفوظة بعناية.", "ru": "Отреставрированный традиционный дом, названный по характерным выступающим деревянным карнизам (saçak), типичным для старой жилой архитектуры Никосии. Сегодня это центр искусства и культуры, где в бережно сохранённой обстановке османской эпохи проходят выставки и мероприятия.", "el": "Αναστηλωμένο παραδοσιακό σπίτι που πήρε το όνομά του από τις χαρακτηριστικές προεξέχουσες ξύλινες μαρκίζες του (saçak), τυπικές της παλιάς οικιστικής αρχιτεκτονικής της Λευκωσίας. Σήμερα λειτουργεί ως κέντρο τεχνών και πολιτισμού και φιλοξενεί εκθέσεις και εκδηλώσεις σε ένα προσεκτικά διατηρημένο περιβάλλον της οθωμανικής εποχής.", "fr": "Maison traditionnelle restaurée, nommée d''après ses avant-toits en bois saillants caractéristiques (saçak), typiques de l''architecture domestique du vieux Nicosie. Devenue centre artistique et culturel, elle accueille expositions et événements dans un cadre d''époque ottomane soigneusement préservé.", "es": "Casa tradicional restaurada que debe su nombre a sus característicos aleros de madera salientes (saçak), típicos de la arquitectura doméstica del viejo Nicosia. Hoy funciona como centro artístico y cultural y acoge exposiciones y eventos en un entorno de época otomana cuidadosamente conservado.", "de": "Ein restauriertes traditionelles Haus, benannt nach seinen markanten vorkragenden Holzdachtraufen (saçak), wie sie für die Wohnarchitektur des alten Nicosia typisch sind. Heute dient es als Kunst- und Kulturzentrum und beherbergt Ausstellungen und Veranstaltungen in einem sorgfältig erhaltenen Ambiente aus osmanischer Zeit.", "fa": "خانه‌ای سنتی و مرمت‌شده که نامش را از لبه‌های چوبی بیرون‌زده و متمایز بامش (ساچاک) گرفته است؛ ویژگی رایج معماری مسکونی نیکوزیای قدیم. این خانه اکنون به‌عنوان مرکز هنری و فرهنگی استفاده می‌شود و میزبان نمایشگاه‌ها و رویدادهایی در فضایی از دوره عثمانی است که با دقت حفظ شده است."}'::jsonb),  -- Saçaklı House
  ('1ed9139d-453c-4eba-948b-b8431487c9f0'::uuid, '6e38b3fa34b984c3986f34272abf78f8', '{"ar": "كنيسة دير ذات قبتين على أطراف مقبرة سلاميس، مكرّسة للقديس برنابا، شفيع قبرص، الذي يقع قبره في كنيسة صغيرة قريبة. وتعمل اليوم متحفًا للأيقونات والآثار يضم قطعًا تمتد من العصر البرونزي فصاعدًا.", "ru": "Двухкупольная монастырская церковь на краю некрополя Саламина, посвящённая святому Варнаве, покровителю Кипра; его гробница находится в часовне неподалёку. Сегодня здесь музей икон и археологии с артефактами начиная с бронзового века.", "el": "Δίτρουλη μοναστηριακή εκκλησία στην άκρη της νεκρόπολης της Σαλαμίνας, αφιερωμένη στον Απόστολο Βαρνάβα, προστάτη άγιο της Κύπρου, του οποίου ο τάφος βρίσκεται σε κοντινό παρεκκλήσι. Σήμερα λειτουργεί ως μουσείο εικόνων και αρχαιολογίας, με ευρήματα από την Εποχή του Χαλκού και μετά.", "fr": "Église monastique à deux coupoles, en bordure de la nécropole de Salamis, dédiée à Barnabé, saint patron de Chypre, dont le tombeau se trouve dans une chapelle voisine. Elle abrite aujourd''hui un musée d''icônes et d''archéologie présentant des objets allant de l''âge du bronze à des époques plus récentes.", "es": "Iglesia monástica de dos cúpulas situada en el límite de la necrópolis de Salamis, dedicada a Bernabé, patrón de Chipre, cuya tumba se encuentra en una capilla cercana. Hoy alberga un museo de iconos y de arqueología con piezas que abarcan desde la Edad del Bronce en adelante.", "de": "Eine Klosterkirche mit zwei Kuppeln am Rand der Nekropole von Salamis, geweiht dem heiligen Barnabas, dem Schutzpatron Zyperns, dessen Grab in einer nahen Kapelle liegt. Heute dient sie als Ikonen- und Archäologiemuseum mit Fundstücken von der Bronzezeit an.", "fa": "کلیسای صومعه‌ای با دو گنبد در حاشیه گورستان باستانی سالامیس که به برنابا، قدیس حامی قبرس، تقدیم شده و آرامگاه او در نمازخانه‌ای در همان نزدیکی قرار دارد. این مکان اکنون موزه شمایل و باستان‌شناسی است و آثاری از عصر مفرغ به بعد را در خود دارد."}'::jsonb),  -- St. Barnabas Monastery
  ('9abee5c9-0d44-4a34-abef-04e3260151d1'::uuid, '24eaed8f2ebb78931dc31e23af904b8d', '{"ar": "قلعة لوزينيانية من القرن الرابع عشر تحرس ميناء فاماغوستا، أعاد البنادقة تشكيلها لاحقًا لتصبح حصنًا مدفعيًا بأربعة أبراج دائرية. يربطها اسمها بمسرحية شكسبير، ولا يزال فناؤها يحتفظ بقذائف مدفعية عثمانية وإسبانية.", "ru": "Замок Лузиньянов XIV века, охранявший гавань Фамагусты; позднее венецианцы перестроили его в артиллерийскую крепость с четырьмя круглыми башнями. Своим названием он связан с пьесой Шекспира, а в его дворе до сих пор лежат османские и испанские пушечные ядра.", "el": "Λουζινιανό κάστρο του 14ου αιώνα που φύλαγε το λιμάνι της Αμμοχώστου και αργότερα μετατράπηκε από τους Ενετούς σε φρούριο πυροβολικού με τέσσερις κυκλικούς πύργους. Το όνομά του το συνδέει με το έργο του Σαίξπηρ, ενώ στην αυλή του βρίσκονται ακόμη οθωμανικές και ισπανικές οβίδες.", "fr": "Château des Lusignan du XIVe siècle gardant le port de Famagouste, transformé plus tard par les Vénitiens en forteresse d''artillerie dotée de quatre tours rondes. Son nom le rattache à la pièce de Shakespeare, et sa cour conserve encore des boulets de canon ottomans et espagnols.", "es": "Castillo lusiñano del siglo XIV que custodia el puerto de Famagusta, remodelado después por los venecianos como fortaleza de artillería con cuatro torres redondas. Su nombre lo vincula a la obra de Shakespeare, y en su patio aún se conservan balas de cañón otomanas y españolas.", "de": "Eine Lusignan-Burg aus dem 14. Jahrhundert, die den Hafen von Famagusta bewacht und später von den Venezianern zu einer Artilleriefestung mit vier Rundtürmen umgebaut wurde. Ihr Name verbindet sie mit Shakespeares Drama, und im Hof liegen noch heute osmanische und spanische Kanonenkugeln.", "fa": "قلعه‌ای لوزینیانی از قرن چهاردهم که از بندر فاماگوستا محافظت می‌کند و بعدها ونیزی‌ها آن را به دژی توپخانه‌ای با چهار برج مدور تبدیل کردند. نامش آن را به نمایشنامه شکسپیر پیوند می‌دهد و حیاطش هنوز گلوله‌های توپ عثمانی و اسپانیایی را در خود دارد."}'::jsonb),  -- Othello Castle
  ('e78e6e44-c9d0-4090-ab15-02cb63b9d36c'::uuid, 'db7716c9db41439503e2d06ffbef0d7c', '{"ar": "متحف داخل المدينة المسوّرة بجوار مسجد لالا مصطفى باشا، يقع في المبنى الذي سُجن فيه الشاعر والكاتب المسرحي العثماني نامق كمال في سبعينيات القرن التاسع عشر. ويحافظ على زنزانته ويعرض مقتنيات عن حياته وأعماله.", "ru": "Музей в обнесённом стенами старом городе рядом с мечетью Лала Мустафы-паши, в здании, где в 1870-х годах находился в заключении османский поэт и драматург Намык Кемаль. Здесь сохранена его камера и представлена экспозиция о его жизни и творчестве.", "el": "Μουσείο στην εντός των τειχών πόλη, δίπλα στο τέμενος Λαλά Μουσταφά Πασά, στο κτίριο όπου φυλακίστηκε τη δεκαετία του 1870 ο Οθωμανός ποιητής και θεατρικός συγγραφέας Ναμίκ Κεμάλ. Διατηρεί το κελί του και παρουσιάζει εκθέματα για τη ζωή και το έργο του.", "fr": "Musée de la vieille ville fortifiée, à côté de la mosquée Lala Mustafa Pasha, installé dans le bâtiment où le poète et dramaturge ottoman Namık Kemal fut emprisonné dans les années 1870. On y voit sa cellule ainsi que des expositions sur sa vie et son œuvre.", "es": "Museo en la ciudad amurallada, junto a la Mezquita de Lala Mustafa Pasha, instalado en el edificio donde estuvo encarcelado en la década de 1870 el poeta y dramaturgo otomano Namık Kemal. Conserva su celda y exposiciones sobre su vida y su obra.", "de": "Ein Museum in der ummauerten Altstadt neben der Lala-Mustafa-Pasha-Moschee, untergebracht in dem Gebäude, in dem der osmanische Dichter und Dramatiker Namık Kemal in den 1870er-Jahren inhaftiert war. Erhalten sind seine Zelle sowie Ausstellungen zu seinem Leben und Werk.", "fa": "موزه‌ای در شهر حصاردار، در کنار مسجد لالا مصطفی پاشا، در بنایی که نامق کمال، شاعر و نمایشنامه‌نویس عثمانی، در دهه ۱۸۷۰ در آن زندانی بود. سلول او حفظ شده و نمایشگاهی از زندگی و آثارش برپاست."}'::jsonb),  -- Namık Kemal Museum & Dungeon
  ('8283f858-f93f-4419-9f8d-a88fc99602cd'::uuid, 'e94798b6cc48cef9183478f537b2748f', '{"ar": "متحف يقع في حصن جانبولاد عند الزاوية الجنوبية الشرقية للأسوار البندقية، ويحمل اسم القائد العثماني الذي سقط أثناء الاستيلاء على البرج خلال حصار عام 1571. يضم ضريحه ومعروضات عن حصار فاماغوستا.", "ru": "Музей в бастионе Джанбулат в юго-восточном углу венецианских стен, названном в честь османского военачальника, павшего при взятии этой башни во время осады 1571 года. Здесь находятся его гробница и экспозиция об осаде Фамагусты.", "el": "Μουσείο στον προμαχώνα Τζανμπουλάτ, στη νοτιοανατολική γωνία των ενετικών τειχών, που φέρει το όνομα του Οθωμανού διοικητή ο οποίος έπεσε καταλαμβάνοντας τον πύργο κατά την πολιορκία του 1571. Στεγάζει τον τάφο του και εκθέματα για την πολιορκία της Αμμοχώστου.", "fr": "Musée installé dans le bastion Canbulat, à l''angle sud-est des remparts vénitiens, qui porte le nom du commandant ottoman tombé en prenant la tour lors du siège de 1571. Il abrite son tombeau et des expositions consacrées au siège de Famagouste.", "es": "Museo situado en el bastión de Canbulat, en la esquina sureste de las murallas venecianas, que lleva el nombre del comandante otomano caído al tomar la torre durante el asedio de 1571. Alberga su tumba y exposiciones sobre el asedio de Famagusta.", "de": "Ein Museum in der Canbulat-Bastei an der Südostecke der venezianischen Stadtmauer, benannt nach dem osmanischen Befehlshaber, der bei der Eroberung des Turms während der Belagerung von 1571 fiel. Es beherbergt sein Grab sowie Ausstellungen zur Belagerung von Famagusta.", "fa": "موزه‌ای در باروی جان‌بولات در گوشه جنوب‌شرقی حصار ونیزی که به نام فرمانده عثمانی‌ای نام‌گذاری شده که هنگام تصرف این برج در محاصره سال ۱۵۷۱ کشته شد. آرامگاه او و نمایشگاهی درباره محاصره فاماگوستا در این موزه قرار دارد."}'::jsonb),  -- Canbulat Museum
  ('28f69a7c-48f1-4a51-b84e-37beda5e29b8'::uuid, '16c119bd907dc9aaa6daf885e7d765ce', '{"ar": "من أهم المواقع الأثرية في قبرص. تأسست سلاميس في القرن الحادي عشر قبل الميلاد، وكانت من أهم المدن الممالك في العالم القديم. يضم الموقع صالة رياضية (جمنازيوم) كبيرة وحمّامات رومانية ومسرحًا رومانيًا وفسيفساء واسعة، وكلها وسط غابة صنوبر مفتوحة قرب البحر.", "ru": "Один из важнейших античных памятников Кипра. Основанный в XI веке до н. э., Саламин был одним из самых значительных городов-царств древнего мира. На территории — большой гимнасий, римские термы, римский театр и обширные мозаики, и всё это среди светлого соснового леса у моря.", "el": "Ένας από τους σημαντικότερους αρχαιολογικούς χώρους της Κύπρου. Ιδρυμένη τον 11ο αιώνα π.Χ., η Σαλαμίνα ήταν μία από τις σημαντικότερες πόλεις-βασίλεια του αρχαίου κόσμου. Ο χώρος περιλαμβάνει μεγάλο γυμνάσιο, ρωμαϊκά λουτρά, ρωμαϊκό θέατρο και εκτεταμένα ψηφιδωτά — όλα μέσα σε αραιό πευκοδάσος κοντά στη θάλασσα.", "fr": "L''un des sites antiques les plus importants de Chypre. Fondée au XIe siècle av. J.-C., Salamis fut l''une des cités-royaumes majeures du monde antique. Le site comprend un vaste gymnase, des thermes romains, un théâtre romain et de nombreuses mosaïques, le tout dans une pinède clairsemée près de la mer.", "es": "Uno de los yacimientos antiguos más importantes de Chipre. Fundada en el siglo XI a. C., Salamis fue una de las ciudades-reino más destacadas del mundo antiguo. El yacimiento incluye un gran gimnasio, termas romanas, un teatro romano y numerosos mosaicos, todo ello en un pinar abierto junto al mar.", "de": "Eine der bedeutendsten antiken Stätten Zyperns. Das im 11. Jahrhundert v. Chr. gegründete Salamis war eines der wichtigsten Stadtkönigreiche der antiken Welt. Zur Anlage gehören ein großes Gymnasion, römische Thermen, ein römisches Theater und zahlreiche Mosaiken – alles in lichtem Pinienwald nahe dem Meer.", "fa": "یکی از مهم‌ترین محوطه‌های باستانی قبرس. سالامیس که در قرن یازدهم پیش از میلاد بنیان نهاده شد، یکی از مهم‌ترین دولت‌شهرهای پادشاهی جهان باستان بود. این محوطه شامل یک ورزشگاه (گیمنازیوم) بزرگ، حمام‌های رومی، یک تئاتر رومی و موزاییک‌های گسترده است که همگی در میان جنگل باز کاج و نزدیک دریا قرار دارند.", "en": "One of the most significant ancient sites in Cyprus. Founded in the 11th century BC, Salamis was one of the most important city-kingdoms of the ancient world. The site includes a large gymnasium, Roman baths, a Roman theatre, and extensive mosaics — all set in open pine woodland near the sea.", "tr": "Kıbrıs''ın en önemli antik kentlerinden biri. MÖ 11. yüzyılda kurulan Salamis, antik dünyanın büyük şehir krallıklarından biriydi. Denize yakın çam ormanlığında büyük bir jimnasyon, Roma hamamları, Roma tiyatrosu ve geniş mozaikler yer almaktadır."}'::jsonb),  -- Salamis Ancient City
  ('88def13a-3ee3-4c3b-bb7b-56bf15f27f33'::uuid, 'a41735b8ddf042068dd6cce143449c8c', '{"ar": "أقصى القلاع الصليبية الثلاث شرقًا على امتداد السلسلة الجبلية الشمالية، وتحرس الطريق المؤدي إلى شبه جزيرة كارباس. بيزنطية الأصل ووسّعها اللوزينيان، وتطل أطلالها على مناظر شاملة للساحلين.", "ru": "Самый восточный из трёх замков крестоносцев на северном хребте, охранявший подступы к полуострову Карпаз. Византийский по происхождению и расширенный Лузиньянами, с его руин открываются широкие виды на оба побережья.", "el": "Το ανατολικότερο από τα τρία κάστρα των Σταυροφόρων στη βόρεια οροσειρά, που φύλαγε την πρόσβαση στη χερσόνησο της Karpaz (Καρπασία). Βυζαντινής προέλευσης και επεκταμένο από τους Λουζινιανούς, τα ερείπιά του προσφέρουν πανοραμική θέα και στις δύο ακτές.", "fr": "Le plus oriental des trois châteaux croisés de la chaîne septentrionale, gardant l''accès à la péninsule du Karpaz. D''origine byzantine et agrandi par les Lusignan, il offre depuis ses ruines de vastes panoramas sur les deux côtes.", "es": "El más oriental de los tres castillos cruzados de la cordillera septentrional, que custodia el acceso a la península de Karpaz. De origen bizantino y ampliado por los Lusignan, sus ruinas dominan amplias vistas sobre ambas costas.", "de": "Die östlichste der drei Kreuzritterburgen im nördlichen Gebirgszug, die den Zugang zur Halbinsel Karpaz bewacht. Byzantinischen Ursprungs und von den Lusignans erweitert, bieten ihre Ruinen weite Ausblicke über beide Küsten.", "fa": "شرقی‌ترین قلعه از سه قلعه صلیبی در امتداد رشته‌کوه شمالی که راه ورود به شبه‌جزیره کارپاس را پاس می‌دارد. این قلعه ریشه بیزانسی دارد و لوزینیان‌ها آن را گسترش دادند؛ ویرانه‌هایش چشم‌اندازی گسترده بر هر دو ساحل دارد."}'::jsonb),  -- Kantara Castle
  ('204d484c-8297-46e3-8306-38bfe0beb3c2'::uuid, '2da36277c0e58b308c3704d1b7692e10', '{"ar": "بقايا مدينة من العصر البرونزي المتأخر كانت أحد المراكز الرئيسية لتجارة النحاس في قبرص قبل أكثر من 3000 عام. كشفت الحفريات هنا عن مقابر غنية وتمثال «الإله ذي القرنين» البرونزي الشهير.", "ru": "Руины города позднего бронзового века, который более 3000 лет назад был одним из главных центров торговли медью на Кипре. При раскопках здесь были обнаружены богатые гробницы и знаменитая бронзовая статуэтка Рогатого бога.", "el": "Τα ερείπια μιας πόλης της Ύστερης Εποχής του Χαλκού, που πριν από περισσότερα από 3.000 χρόνια ήταν ένα από τα κύρια κέντρα εμπορίου χαλκού της Κύπρου. Οι ανασκαφές έφεραν στο φως πλούσιους τάφους και το περίφημο χάλκινο ειδώλιο του Κερασφόρου Θεού.", "fr": "Vestiges d''une cité de la fin de l''âge du bronze qui fut, il y a plus de 3 000 ans, l''un des principaux centres du commerce du cuivre à Chypre. Les fouilles y ont mis au jour de riches tombes et la célèbre statuette en bronze du Dieu cornu.", "es": "Restos de una ciudad de finales de la Edad del Bronce que fue, hace más de 3.000 años, uno de los principales centros del comercio del cobre en Chipre. Las excavaciones sacaron a la luz ricas tumbas y la famosa figura de bronce del Dios con cuernos.", "de": "Die Überreste einer spätbronzezeitlichen Stadt, die vor mehr als 3.000 Jahren eines der wichtigsten Zentren des zyprischen Kupferhandels war. Bei Ausgrabungen kamen reich ausgestattete Gräber und die berühmte Bronzefigur des Gehörnten Gottes zutage.", "fa": "بقایای شهری از اواخر عصر مفرغ که بیش از ۳۰۰۰ سال پیش یکی از مراکز اصلی تجارت مس قبرس بود. کاوش‌ها در اینجا گورهایی غنی و پیکره مفرغی مشهور «خدای شاخ‌دار» را آشکار کرد."}'::jsonb),  -- Enkomi (Alasia)
  ('4c340455-f0af-4d1a-88c6-e6cfdc41c978'::uuid, '845fa40b7d39943d536590bee2ad11de', '{"ar": "مقبرة تضم مدافن ضخمة من القرنين الثامن والسابع قبل الميلاد قرب سلاميس، حيث دُفن ملوك قبرص مع عرباتهم وخيولهم وقرابين ثمينة، في طقوس تحاكي المدافن التي وصفها هوميروس. ويعرض متحف صغير في الموقع المكتشفات.", "ru": "Некрополь монументальных гробниц VIII–VII веков до н. э. близ Саламина, где кипрских царей хоронили с колесницами, лошадьми и богатыми дарами — подобно погребениям, описанным Гомером. Находки представлены в небольшом музее на месте раскопок.", "el": "Νεκρόπολη με μνημειώδεις τάφους του 8ου–7ου αιώνα π.Χ. κοντά στη Σαλαμίνα, όπου οι βασιλείς της Κύπρου θάβονταν με άρματα, άλογα και πλούσια κτερίσματα, θυμίζοντας τις ταφές που περιγράφει ο Όμηρος. Ένα μικρό επιτόπιο μουσείο εκθέτει τα ευρήματα.", "fr": "Nécropole de tombes monumentales des VIIIe et VIIe siècles av. J.-C., près de Salamis, où les rois chypriotes étaient inhumés avec chars, chevaux et riches offrandes, rappelant les funérailles décrites par Homère. Un petit musée sur place présente les découvertes.", "es": "Necrópolis de tumbas monumentales de los siglos VIII y VII a. C. cerca de Salamis, donde los reyes chipriotas eran enterrados con carros, caballos y ricas ofrendas, que evocan los funerales descritos por Homero. Un pequeño museo en el recinto expone los hallazgos.", "de": "Eine Nekropole mit monumentalen Gräbern aus dem 8. bis 7. Jahrhundert v. Chr. nahe Salamis, in denen zyprische Könige mit Streitwagen, Pferden und reichen Beigaben bestattet wurden – ein Echo der von Homer beschriebenen Bestattungen. Ein kleines Museum vor Ort zeigt die Funde.", "fa": "گورستانی از مقبره‌های عظیم قرن هشتم تا هفتم پیش از میلاد در نزدیکی سالامیس، جایی که پادشاهان قبرس همراه با ارابه‌ها، اسب‌ها و هدایای گران‌بها به خاک سپرده می‌شدند؛ تدفین‌هایی که یادآور توصیفات هومر است. موزه کوچکی در محل، یافته‌ها را به نمایش می‌گذارد."}'::jsonb),  -- Royal Tombs
  ('2c20f82e-1ee1-4c9b-9fdc-f59be72da470'::uuid, '281f0e110dc652600c61f255e4905eb8', '{"ar": "كنيسة بيزنطية ذات قبة في إسكيله (تريكومو)، يعود بعض أجزائها إلى القرن الثاني عشر، وتحتفظ بلوحات جدارية من فترات عدة. وهي تعمل اليوم متحفًا للأيقونات.", "ru": "Купольная византийская церковь в Искеле (Трикомо), отдельные части которой относятся к XII веку; в ней сохранились фрески разных периодов. Сегодня здесь размещается музей икон.", "el": "Τρουλαία βυζαντινή εκκλησία στο İskele (Τρίκωμο), τμήματα της οποίας χρονολογούνται από τον 12ο αιώνα, με τοιχογραφίες από διάφορες περιόδους. Σήμερα λειτουργεί ως μουσείο εικόνων.", "fr": "Église byzantine à coupole située à İskele (Trikomo), dont certaines parties remontent au XIIe siècle et qui conserve des fresques de plusieurs époques. Elle abrite aujourd''hui un musée d''icônes.", "es": "Iglesia bizantina con cúpula en İskele (Trikomo), con partes que datan del siglo XII y frescos de varios periodos. Hoy funciona como museo de iconos.", "de": "Eine byzantinische Kuppelkirche in İskele (Trikomo), deren älteste Teile aus dem 12. Jahrhundert stammen und die Fresken aus mehreren Epochen bewahrt. Heute dient sie als Ikonenmuseum.", "fa": "کلیسایی گنبددار و بیزانسی در ایسکله (تریکومو) که بخش‌هایی از آن به قرن دوازدهم بازمی‌گردد و نقاشی‌های دیواری چند دوره را حفظ کرده است. این کلیسا اکنون موزه شمایل است."}'::jsonb),  -- İskele Icon Museum (Panagia Theotokos)
  ('2532c8db-14ec-4aa7-a949-abfa7c49e735'::uuid, '4a56ed088409872234c8f33540363243', '{"ar": "حصن الرافلين الذي يحرس بوابة البر في أسوار فاماغوستا البندقية. استولى عليه العثمانيون عام 1571 ورفعوا فوقه راية بيضاء، فاكتسب الاسم التركي «آق قوله» (البرج الأبيض)؛ ويمكن استكشاف غرفه المقببة وأسواره.", "ru": "Бастион-равелин, охраняющий Сухопутные ворота венецианских стен Фамагусты. Взявшие его в 1571 году османы подняли над ним белый флаг, и он получил турецкое название Аккуле («Белая башня»); его сводчатые помещения и валы открыты для осмотра.", "el": "Ο προμαχώνας Ραβελίνος που φύλαγε την Πύλη της Ξηράς στα ενετικά τείχη της Αμμοχώστου. Οι Οθωμανοί, που τον κατέλαβαν το 1571, ύψωσαν πάνω του λευκή σημαία, κι έτσι πήρε το τουρκικό όνομα Akkule («Λευκός Πύργος»)· οι θολωτοί θάλαμοι και οι επάλξεις του είναι επισκέψιμοι.", "fr": "Le bastion du Ravelin, qui garde la porte de Terre des remparts vénitiens de Famagouste. Pris en 1571 par les Ottomans, qui y hissèrent un drapeau blanc, il reçut le nom turc d''Akkule (« Tour blanche ») ; ses salles voûtées et ses remparts se prêtent à la visite.", "es": "El bastión del Ravelín, que custodia la Puerta de Tierra de las murallas venecianas de Famagusta. Tomado en 1571 por los otomanos, que izaron en él una bandera blanca, recibió el nombre turco de Akkule (Torre Blanca); se pueden recorrer sus salas abovedadas y sus murallas.", "de": "Die Ravelin-Bastei, die das Landtor der venezianischen Stadtmauer von Famagusta bewacht. Nach der Einnahme 1571 hissten die Osmanen darauf eine weiße Flagge, wodurch sie den türkischen Namen Akkule („Weißer Turm“) erhielt; ihre gewölbten Kammern und Wehrgänge können erkundet werden.", "fa": "باروی راولین که از دروازه زمینی حصار ونیزی فاماگوستا محافظت می‌کند. عثمانی‌ها در سال ۱۵۷۱ آن را تصرف کردند و پرچمی سفید بر فرازش برافراشتند و از همین رو نام ترکی آق‌قوله (برج سفید) را گرفت؛ اتاق‌های طاق‌دار و باروهای آن برای بازدید باز است."}'::jsonb),  -- Akkule (Ravelin Bastion)
  ('c83ed380-27a9-4c3d-abf0-859e09a0a5bf'::uuid, '0c5a9bb2bf01880af7ef1b382c8f82cf', '{"ar": "بقايا بازيليكا مسيحية مبكرة من القرن الخامس في سيباهي بمنطقة كارباس، وتتميز بأرضياتها الفسيفسائية الهندسية والتصويرية المحفوظة بشكل استثنائي. وهي من أروع المواقع البيزنطية المبكرة في شبه الجزيرة.", "ru": "Руины раннехристианской базилики V века в Сипахи на Карпазе, примечательной исключительно хорошо сохранившимися мозаичными полами с геометрическими и фигурными сюжетами. Это один из лучших ранневизантийских памятников полуострова.", "el": "Τα ερείπια μιας παλαιοχριστιανικής βασιλικής του 5ου αιώνα στο Sipahi (Αγία Τριάδα) της Karpaz (Καρπασία), αξιοσημείωτης για τα εξαιρετικά καλοδιατηρημένα γεωμετρικά και εικονιστικά ψηφιδωτά δάπεδά της. Είναι ένας από τους ωραιότερους πρωτοβυζαντινούς χώρους της χερσονήσου.", "fr": "Vestiges d''une basilique paléochrétienne du Ve siècle à Sipahi, dans le Karpaz, remarquable pour ses pavements de mosaïques géométriques et figuratives exceptionnellement bien conservés. C''est l''un des plus beaux sites protobyzantins de la péninsule.", "es": "Restos de una basílica paleocristiana del siglo V en Sipahi, en el Karpaz, notable por sus suelos de mosaicos geométricos y figurativos excepcionalmente bien conservados. Es uno de los mejores yacimientos bizantinos tempranos de la península.", "de": "Die Überreste einer frühchristlichen Basilika aus dem 5. Jahrhundert in Sipahi auf dem Karpaz, bemerkenswert für ihre außergewöhnlich gut erhaltenen geometrischen und figürlichen Mosaikböden. Sie zählt zu den schönsten frühbyzantinischen Stätten der Halbinsel.", "fa": "بقایای یک باسیلیکای مسیحی اولیه از قرن پنجم در سیپاهی در منطقه کارپاس که به‌خاطر کف‌پوش‌های موزاییکی هندسی و تصویری با حفاظت فوق‌العاده‌اش شهرت دارد. این مکان یکی از بهترین محوطه‌های اوایل دوره بیزانس در این شبه‌جزیره است."}'::jsonb),  -- Ayios Trias Basilica
  ('d2403dda-2a30-4e96-bb3a-b1f90249284b'::uuid, '6162b30869c1e38985853a1114d93f2d', '{"ar": "متحف إقليمي للآثار في إسكيله يعرض مكتشفات من المنطقة المحيطة، تمتد عبر عصور ما قبل التاريخ والعصر الكلاسيكي والعصر البيزنطي.", "ru": "Региональный археологический музей в Искеле, где представлены находки из окрестностей, охватывающие доисторический, классический и византийский периоды.", "el": "Περιφερειακό αρχαιολογικό μουσείο στο İskele, που εκθέτει ευρήματα από τη γύρω περιοχή, από την προϊστορική, την κλασική και τη βυζαντινή περίοδο.", "fr": "Musée archéologique régional à İskele présentant des découvertes des environs, de la préhistoire aux époques classique et byzantine.", "es": "Museo arqueológico regional en İskele que expone hallazgos de la comarca, desde la prehistoria hasta las épocas clásica y bizantina.", "de": "Ein regionales Archäologiemuseum in İskele mit Funden aus der Umgebung, die von der Vorgeschichte über die klassische bis zur byzantinischen Zeit reichen.", "fa": "موزه باستان‌شناسی منطقه‌ای در ایسکله که یافته‌هایی از ناحیه پیرامون را از دوره‌های پیش از تاریخ، کلاسیک و بیزانسی به نمایش می‌گذارد."}'::jsonb),  -- İskele Archaeological Museum
  ('7ecf2c84-2192-45c9-b075-a2ce115f842c'::uuid, 'b3a38312cfbf164939e00877468eaa58', '{"ar": "قلعة من العهد البيزنطي أعاد البنادقة والعثمانيون بناءها وتوسيعها، وتقع عند مدخل ميناء كيرينيا. تضم متحف حطام السفن، الذي يحتضن سفينة تجارية عمرها 2300 عام انتُشلت من قاع البحر. والإطلالات على الميناء من فوق الأسوار رائعة.", "ru": "Замок византийской эпохи у входа в гавань Кирении, перестроенный и расширенный венецианцами и османами. В нём находится Музей кораблекрушений, где хранится торговое судно возрастом 2300 лет, поднятое с морского дна. С крепостных стен открывается великолепный вид на гавань.", "el": "Κάστρο της βυζαντινής εποχής στην είσοδο του λιμανιού της Κερύνειας, που ανοικοδομήθηκε και επεκτάθηκε από τους Ενετούς και τους Οθωμανούς. Στεγάζει το Μουσείο Ναυαγίου, με ένα εμπορικό πλοίο 2.300 ετών που ανελκύστηκε από τον βυθό. Η θέα στο λιμάνι από τις επάλξεις είναι εξαιρετική.", "fr": "Château d''époque byzantine, reconstruit et agrandi par les Vénitiens et les Ottomans, à l''entrée du port de Kyrenia. Il abrite le musée de l''Épave, qui présente un navire marchand vieux de 2 300 ans remonté du fond de la mer. Depuis les remparts, la vue sur le port est superbe.", "es": "Castillo de época bizantina, reconstruido y ampliado por venecianos y otomanos, situado a la entrada del puerto de Kyrenia. Alberga el Museo del Naufragio, que conserva un barco mercante de 2.300 años recuperado del fondo marino. Las vistas del puerto desde las almenas son excelentes.", "de": "Eine Burg aus byzantinischer Zeit, von Venezianern und Osmanen wiederaufgebaut und erweitert, an der Einfahrt zum Hafen von Kyrenia. Sie beherbergt das Schiffswrackmuseum mit einem 2.300 Jahre alten Handelsschiff, das vom Meeresgrund geborgen wurde. Von den Zinnen bietet sich ein hervorragender Blick auf den Hafen.", "fa": "قلعه‌ای از دوران بیزانس که ونیزی‌ها و عثمانی‌ها آن را بازسازی و گسترش دادند و در ورودی بندر کیرنیا قرار دارد. موزه کشتی‌های غرق‌شده در آن جای دارد که یک کشتی تجاری ۲۳۰۰ ساله بیرون‌کشیده از بستر دریا را در خود نگه می‌دارد. چشم‌انداز بندر از فراز باروها عالی است.", "en": "A Byzantine-era castle rebuilt and expanded by the Venetians and Ottomans, sitting at the entrance to Kyrenia Harbour. Houses the Shipwreck Museum, home to a 2,300-year-old merchant vessel recovered from the seabed. The harbour views from the battlements are excellent.", "tr": "Venedikliler ve Osmanlılar tarafından yeniden inşa edilip genişletilen Bizans dönemi kalesi, Girne Limanı girişinde yer almaktadır. Deniz tabanından çıkarılan 2.300 yıllık bir ticaret gemisine ev sahipliği yapan Batık Gemi Müzesi burada bulunur. Burçlardan liman manzarası nefes kesicidir."}'::jsonb),  -- Kyrenia Castle
  ('d1d9761c-a9e8-4f62-8b3b-4c0b6b8fdf7c'::uuid, '05cf6ef91d7857cebe6ccaa3e9a9651a', '{"ar": "دير قوطي من القرن الثالث عشر في قرية بيلابايس الواقعة على سفح التل، ويُعدّ أروع نموذج للعمارة القوطية في قبرص. وقاعة الطعام والرواق محفوظان جيدًا. عاش لورانس داريل في القرية وكتب عنها في «ليمون قبرص المر».", "ru": "Готический монастырь XIII века в деревне Беллапаис на склоне холма, считающийся лучшим образцом готической архитектуры на Кипре. Трапезная и клуатр хорошо сохранились. В деревне жил Лоуренс Даррелл, описавший её в книге «Горькие лимоны».", "el": "Γοτθικό μοναστήρι του 13ου αιώνα στο ορεινό χωριό Μπελαπάις, που θεωρείται το ωραιότερο δείγμα γοτθικής αρχιτεκτονικής στην Κύπρο. Η τραπεζαρία και το περιστύλιο σώζονται σε καλή κατάσταση. Ο Λόρενς Ντάρελ έζησε στο χωριό και έγραψε γι'' αυτό στο βιβλίο «Πικρολέμονα».", "fr": "Monastère gothique du XIIIe siècle dans le village perché de Bellapais, considéré comme le plus bel exemple d''architecture gothique de Chypre. Le réfectoire et le cloître sont bien conservés. Lawrence Durrell vécut dans le village et l''évoqua dans « Citrons acides ».", "es": "Monasterio gótico del siglo XIII en el pueblo de ladera de Bellapais, considerado el mejor ejemplo de arquitectura gótica de Chipre. El refectorio y el claustro están bien conservados. Lawrence Durrell vivió en el pueblo y escribió sobre él en «Limones amargos».", "de": "Ein gotisches Kloster aus dem 13. Jahrhundert im Hangdorf Bellapais, das als schönstes Beispiel gotischer Architektur auf Zypern gilt. Refektorium und Kreuzgang sind gut erhalten. Lawrence Durrell lebte im Dorf und schrieb darüber in „Bittere Limonen“.", "fa": "صومعه‌ای گوتیک از قرن سیزدهم در روستای کوهپایه‌ای بلاپایس که بهترین نمونه معماری گوتیک در قبرس به شمار می‌رود. تالار غذاخوری و صحن سرپوشیده آن به‌خوبی حفظ شده‌اند. لارنس دارل در این روستا زندگی می‌کرد و در «لیموهای تلخ قبرس» درباره آن نوشت."}'::jsonb),  -- Bellapais Abbey
  ('d773e658-95ac-48ba-ae53-5936374a976f'::uuid, '84b7210abf8b254a47bf7cf727fbd3e2', '{"ar": "قلعة من العصور الوسطى تجثم على قمة جبل فوق كيرينيا على ارتفاع 732 مترًا. بناها البيزنطيون، وبلغت ذروة استخدامها في عهد اللوزينيان. ويوفر الجناح العلوي إطلالات شاملة على الساحل الشمالي وسهل ميساوريا معًا. ويُقال إنها ألهمت قلعة «بياض الثلج» لدى ديزني.", "ru": "Средневековый замок на горной вершине над Киренией, на высоте 732 м. Построенный византийцами, наибольшее значение он приобрёл при Лузиньянах. С верхнего двора открываются широкие виды на северное побережье и равнину Месаория. Говорят, что он вдохновил создателей замка из диснеевской «Белоснежки».", "el": "Μεσαιωνικό κάστρο σκαρφαλωμένο σε βουνοκορφή πάνω από την Κερύνεια, σε υψόμετρο 732 μ. Χτισμένο από τους Βυζαντινούς, γνώρισε τη μεγαλύτερη ακμή του επί Λουζινιανών. Ο άνω περίβολος προσφέρει πανοραμική θέα τόσο στη βόρεια ακτή όσο και στην πεδιάδα της Μεσαορίας. Λέγεται ότι ενέπνευσε το κάστρο της «Χιονάτης» της Disney.", "fr": "Château médiéval perché à 732 m d''altitude sur un sommet dominant Kyrenia. Bâti par les Byzantins, il connut son apogée sous les Lusignan. L''enceinte haute offre de vastes panoramas sur la côte nord et la plaine de la Mésorée. Il aurait inspiré le château de Blanche-Neige de Disney.", "es": "Castillo medieval encaramado en una cumbre sobre Kyrenia, a 732 m. Construido por los bizantinos, vivió su época de mayor uso bajo los Lusignan. El recinto superior ofrece amplias vistas sobre la costa norte y la llanura de Mesaoria. Se dice que inspiró el castillo de Blancanieves de Disney.", "de": "Eine mittelalterliche Burg auf einem 732 m hohen Berggipfel über Kyrenia. Von den Byzantinern erbaut, erlebte sie ihre Blütezeit unter den Lusignans. Die Oberburg bietet weite Ausblicke über die Nordküste und die Mesaoria-Ebene. Sie soll Disney zum Schloss von Schneewittchen inspiriert haben.", "fa": "قلعه‌ای قرون وسطایی بر فراز قله‌ای کوهستانی در بالای کیرنیا، در ارتفاع ۷۳۲ متری. بیزانسی‌ها آن را ساختند و اوج استفاده از آن در دوره لوزینیان بود. بخش بالایی قلعه چشم‌اندازی گسترده بر ساحل شمالی و دشت مساوریا دارد. گفته می‌شود الهام‌بخش قلعه سفیدبرفی دیزنی بوده است."}'::jsonb),  -- St. Hilarion Castle
  ('39e93795-834b-4ced-bc6d-7890ad96a6a5'::uuid, 'c2e5f1a362b3160da54430bd35c06cb4', '{"ar": "أعلى القلاع الصليبية الثلاث في سلسلة جبال كيرينيا، وتجثم على ارتفاع يزيد على 900 متر فوق الساحل. يُكافأ الزوار بعد صعود شاق بإطلالات مهيبة، وقد كانت أطلالها النائية يومًا مرصدًا وملاذًا.", "ru": "Самый высокий из трёх замков крестоносцев на Киренийском хребте, расположенный более чем в 900 метрах над побережьем. Крутой подъём вознаграждается величественными видами, а его уединённые руины некогда служили наблюдательным пунктом и убежищем.", "el": "Το ψηλότερο από τα τρία κάστρα των Σταυροφόρων στην οροσειρά της Κερύνειας, σκαρφαλωμένο πάνω από 900 μέτρα πάνω από την ακτή. Η απότομη ανάβαση ανταμείβει τους επισκέπτες με επιβλητική θέα, ενώ τα απομονωμένα ερείπιά του χρησίμευαν κάποτε ως παρατηρητήριο και καταφύγιο.", "fr": "Le plus élevé des trois châteaux croisés de la chaîne de Kyrenia, perché à plus de 900 mètres au-dessus de la côte. Une montée raide récompense les visiteurs par des vues imprenables, et ses ruines isolées servirent jadis de poste de guet et de refuge.", "es": "El más alto de los tres castillos cruzados de la cordillera de Kyrenia, encaramado a más de 900 metros sobre la costa. Una empinada subida recompensa al visitante con vistas dominantes, y sus remotas ruinas sirvieron antaño de atalaya y refugio.", "de": "Die höchstgelegene der drei Kreuzritterburgen im Kyrenia-Gebirge, über 900 Meter über der Küste. Ein steiler Aufstieg wird mit beherrschenden Ausblicken belohnt, und die abgelegenen Ruinen dienten einst als Ausguck und Zufluchtsort.", "fa": "بلندترین قلعه از سه قلعه صلیبی رشته‌کوه کیرنیا که بیش از ۹۰۰ متر بالاتر از ساحل جای گرفته است. صعودی پرشیب، بازدیدکنندگان را با چشم‌اندازهایی فراگیر پاداش می‌دهد و ویرانه‌های دورافتاده آن زمانی دیدبانگاه و پناهگاه بوده‌اند."}'::jsonb),  -- Buffavento Castle
  ('8b00fc3e-bb46-4827-b52d-b1b85e692025'::uuid, '9dfcbf3f62cb97e4d9c4314193761b85', '{"ar": "مستودع خرّوب مُرمَّم على واجهة كيرينيا البحرية، يستحضر الحقبة التي كان فيها الخرّوب من أبرز صادرات الجزيرة ويُشحن من هذا الميناء. ويعرض اليوم الحياة المنزلية القبرصية والتاريخ المحلي.", "ru": "Отреставрированный склад рожков на набережной Кирении, напоминающий о временах, когда рожки были важной статьёй экспорта острова и отправлялись из этой гавани. Сегодня здесь представлены быт и местная история Кипра.", "el": "Αναστηλωμένη χαρουπαποθήκη στο παραλιακό μέτωπο της Κερύνειας, που θυμίζει την εποχή όπου τα χαρούπια ήταν σημαντικό εξαγώγιμο προϊόν του νησιού και φορτώνονταν από αυτό το λιμάνι. Σήμερα παρουσιάζει την κυπριακή οικιακή ζωή και την τοπική ιστορία.", "fr": "Entrepôt de caroubes restauré sur le front de mer de Kyrenia, rappelant l''époque où la caroube était un produit d''exportation majeur de l''île, expédié depuis ce port. Il présente aujourd''hui la vie domestique chypriote et l''histoire locale.", "es": "Almacén de algarrobas restaurado en el paseo marítimo de Kyrenia, que evoca la época en que la algarroba era una de las principales exportaciones de la isla y se embarcaba desde este puerto. Hoy muestra la vida doméstica chipriota y la historia local.", "de": "Ein restauriertes Johannisbrot-Lagerhaus an der Uferpromenade von Kyrenia, das an die Zeit erinnert, als Johannisbrot ein wichtiges Exportgut der Insel war und von diesem Hafen aus verschifft wurde. Heute zeigt es das häusliche Leben auf Zypern und die Lokalgeschichte.", "fa": "انبار خرنوب مرمت‌شده‌ای در کرانه کیرنیا که یادآور دورانی است که خرنوب از صادرات اصلی جزیره بود و از همین بندر حمل می‌شد. این مکان اکنون زندگی خانگی قبرسی و تاریخ محلی را معرفی می‌کند."}'::jsonb),  -- Cyprus House & Carob Store Museum
  ('527a51da-a39e-49ff-a2d3-ac07ca3591ad'::uuid, '053eefeb1071d41390259b0ebcb17d6a', '{"ar": "متحف في الهواء الطلق في قره أوغلان أوغلو قرب موقع الإنزال التركي في يوليو 1974، يعرض مركبات عسكرية وطائرات ومدافع إلى جانب نصب تذكاري لمن سقطوا.", "ru": "Музей под открытым небом в Караогланоглу, недалеко от места турецкой высадки в июле 1974 года, где представлены военная техника, самолёты и артиллерия, а также мемориал павшим.", "el": "Υπαίθριο μουσείο στο Karaoğlanoğlu (Άγιος Γεώργιος), κοντά στο σημείο της τουρκικής απόβασης του Ιουλίου 1974, που εκθέτει στρατιωτικά οχήματα, αεροσκάφη και πυροβόλα, μαζί με μνημείο για τους πεσόντες.", "fr": "Musée en plein air à Karaoğlanoğlu, près du lieu du débarquement turc de juillet 1974, présentant véhicules militaires, avions et pièces d''artillerie, ainsi qu''un mémorial aux morts.", "es": "Museo al aire libre en Karaoğlanoğlu, cerca del lugar del desembarco turco de julio de 1974, que expone vehículos militares, aviones y piezas de artillería junto a un monumento a los caídos.", "de": "Ein Freilichtmuseum in Karaoğlanoğlu nahe dem Ort der türkischen Landung im Juli 1974, das Militärfahrzeuge, Flugzeuge und Artillerie zeigt, dazu ein Denkmal für die Gefallenen.", "fa": "موزه‌ای روباز در قره‌اوغلان‌اوغلو، نزدیک محل پیاده‌شدن نیروهای ترکیه در ژوئیه ۱۹۷۴، که خودروهای نظامی، هواپیماها و توپخانه را در کنار یادبودی برای جان‌باختگان به نمایش می‌گذارد."}'::jsonb),  -- Peace and Freedom Museum
  ('975f0204-4007-421a-9dce-d85d7ad9b5be'::uuid, 'dc358e7e6c005abc696ee1a39cfe1212', '{"ar": "كنيسة بيزنطية من القرن الثاني عشر في التلال شرق كيرينيا، تشتهر بتصميمها ذي القبة ولوحاتها الجدارية الباقية من العهدين البيزنطي واللوزينياني.", "ru": "Византийская церковь XII века в холмах к востоку от Кирении, известная своей купольной архитектурой и сохранившимися настенными росписями византийского и лузиньянского периодов.", "el": "Βυζαντινή εκκλησία του 12ου αιώνα στους λόφους ανατολικά της Κερύνειας, γνωστή για τον τρουλαίο σχεδιασμό της και τις σωζόμενες τοιχογραφίες της βυζαντινής και της λουζινιανής περιόδου.", "fr": "Église byzantine du XIIe siècle nichée dans les collines à l''est de Kyrenia, connue pour son plan à coupole et ses peintures murales conservées des époques byzantine et lusignan.", "es": "Iglesia bizantina del siglo XII en las colinas al este de Kyrenia, conocida por su diseño con cúpula y por las pinturas murales conservadas de los periodos bizantino y lusiñano.", "de": "Eine byzantinische Kirche aus dem 12. Jahrhundert in den Hügeln östlich von Kyrenia, bekannt für ihre Kuppelbauweise und erhaltene Wandmalereien aus byzantinischer und lusignanischer Zeit.", "fa": "کلیسایی بیزانسی از قرن دوازدهم در تپه‌های شرق کیرنیا که به‌خاطر طراحی گنبددار و نقاشی‌های دیواری بازمانده از دوره‌های بیزانس و لوزینیان شناخته می‌شود."}'::jsonb),  -- Antiphonitis Church
  ('a95ec495-c1a0-4732-b3dd-55dee1d73351'::uuid, '87f17862b1afda7247a23e04dbd6f25e', '{"ar": "كنيسة من القرن التاسع عشر تطل على ميناء كيرينيا، وبرج جرسها الأبيض المميز معلم محلي بارز، وتضم اليوم مجموعة من الأيقونات الدينية والأدوات الليتورجية.", "ru": "Церковь XIX века над гаванью Кирении, чья характерная белая колокольня стала местной достопримечательностью; сегодня в ней хранится коллекция икон и литургических предметов.", "el": "Εκκλησία του 19ου αιώνα πάνω από το λιμάνι της Κερύνειας, με χαρακτηριστικό λευκό καμπαναριό που αποτελεί τοπικό ορόσημο, η οποία σήμερα στεγάζει συλλογή θρησκευτικών εικόνων και λειτουργικών αντικειμένων.", "fr": "Église du XIXe siècle dominant le port de Kyrenia, dont le clocher blanc caractéristique est un repère local, abritant aujourd''hui une collection d''icônes religieuses et d''objets liturgiques.", "es": "Iglesia del siglo XIX sobre el puerto de Kyrenia, cuyo característico campanario blanco es un referente local, que hoy alberga una colección de iconos religiosos y objetos litúrgicos.", "de": "Eine Kirche aus dem 19. Jahrhundert oberhalb des Hafens von Kyrenia, deren markanter weißer Glockenturm ein örtliches Wahrzeichen ist; heute beherbergt sie eine Sammlung religiöser Ikonen und liturgischer Gegenstände.", "fa": "کلیسایی از قرن نوزدهم بر فراز بندر کیرنیا که برج ناقوس سفید و متمایزش از نشانه‌های شاخص محلی است و اکنون مجموعه‌ای از شمایل‌های مذهبی و اشیای آیینی را در خود جای داده است."}'::jsonb),  -- Archangelos Michael Icon Museum
  ('8cd3a581-7980-4011-b55e-60ab7cf66daa'::uuid, '330ed4bf89954be283594ea731837806', '{"ar": "نصب تذكاري ومتحف في طاشكنت (فونو) يخلّدان ذكرى القرويين الذين قُتلوا في نزاع عام 1974، مع صور ومتعلقات شخصية توثّق الأحداث.", "ru": "Мемориал и музей в деревне Ташкент (Вуно) в память о сельских жителях, погибших в ходе конфликта 1974 года, с фотографиями и личными вещами, документирующими те события.", "el": "Μνημείο και μουσείο στο Taşkent (Βουνό) στη μνήμη των χωρικών που σκοτώθηκαν στη σύγκρουση του 1974, με φωτογραφίες και προσωπικά αντικείμενα που τεκμηριώνουν τα γεγονότα.", "fr": "Mémorial et musée à Taşkent (Vouno) rendant hommage aux villageois tués lors du conflit de 1974, avec photographies et effets personnels retraçant les événements.", "es": "Monumento y museo en Taşkent (Vouno) en memoria de los vecinos del pueblo asesinados en el conflicto de 1974, con fotografías y objetos personales que documentan los hechos.", "de": "Eine Gedenkstätte mit Museum in Taşkent (Vouno), die an die im Konflikt von 1974 getöteten Dorfbewohner erinnert, mit Fotografien und persönlichen Gegenständen, die die Ereignisse dokumentieren.", "fa": "یادمان و موزه‌ای در تاشکنت (وونو) به یاد روستاییانی که در درگیری‌های ۱۹۷۴ کشته شدند، با عکس‌ها و وسایل شخصی که رویدادها را مستند می‌کنند."}'::jsonb),  -- Taşkent Martyrs' Museum
  ('9f14da0c-e9a2-4489-81e2-20973b662942'::uuid, '4d2c801878577790e568cc19e0ff3451', '{"ar": "كنيسة مكرّسة للقديس ماماس بجوار متحف للآثار والتاريخ الطبيعي في غوزيليورت. وتقع الكنيسة، بضريح القديس المزخرف، إلى جانب معروضات من آثار المنطقة والحيوانات القبرصية.", "ru": "Церковь святого Маманта рядом с музеем археологии и естественной истории в Гюзельюрте. Церковь с богато украшенной гробницей святого соседствует с экспозициями местных древностей и кипрской фауны.", "el": "Εκκλησία αφιερωμένη στον Άγιο Μάμα, δίπλα σε μουσείο αρχαιολογίας και φυσικής ιστορίας στο Güzelyurt (Μόρφου). Η εκκλησία, με τον περίτεχνο τάφο του αγίου, βρίσκεται δίπλα σε εκθέσεις τοπικών αρχαιοτήτων και της κυπριακής πανίδας.", "fr": "Église dédiée à saint Mamas, à côté d''un musée d''archéologie et d''histoire naturelle à Güzelyurt. L''église, avec le tombeau richement orné du saint, côtoie des collections d''antiquités régionales et de faune chypriote.", "es": "Iglesia dedicada a San Mamés junto a un museo de arqueología e historia natural en Güzelyurt. La iglesia, con la ornamentada tumba del santo, se encuentra junto a colecciones de antigüedades regionales y fauna chipriota.", "de": "Eine dem heiligen Mamas geweihte Kirche neben einem Museum für Archäologie und Naturgeschichte in Güzelyurt. Die Kirche mit dem reich verzierten Grab des Heiligen steht neben Ausstellungen regionaler Altertümer und der zyprischen Tierwelt.", "fa": "کلیسایی به نام قدیس ماماس در کنار موزه باستان‌شناسی و تاریخ طبیعی در گوزل‌یورت. این کلیسا با آرامگاه پرنقش‌ونگار قدیس، در کنار نمایشگاهی از آثار باستانی منطقه و جانوران قبرس قرار دارد."}'::jsonb),  -- St. Mamas Church & Güzelyurt Museum
  ('8934e983-8eb2-4aa8-9a63-cf0db461dfa6'::uuid, 'c8a8d600c4261880f83c7133299961f7', '{"ar": "أطلال قصر على قمة تل يعود إلى القرن الخامس قبل الميلاد، يطل على البحر قرب ليفكه، ويمزج بين الطرازين المعماريين الفارسي واليوناني. ولا تزال مصاطبه وصهاريجه ترسم مخطط المجمع الملكي.", "ru": "Руины дворца V века до н. э. на вершине холма с видом на море близ Лефке, сочетающего персидский и греческий архитектурные стили. Его террасы и цистерны до сих пор позволяют проследить план царского комплекса.", "el": "Τα ερείπια ενός ανακτόρου του 5ου αιώνα π.Χ. σε λόφο με θέα στη θάλασσα κοντά στο Lefke (Λεύκα), που συνδυάζει περσικά και ελληνικά αρχιτεκτονικά στοιχεία. Οι αναβαθμίδες και οι δεξαμενές του αποτυπώνουν ακόμη την κάτοψη του βασιλικού συγκροτήματος.", "fr": "Ruines perchées d''un palais du Ve siècle av. J.-C. dominant la mer près de Lefke, mêlant styles architecturaux perse et grec. Ses terrasses et citernes dessinent encore le plan du complexe royal.", "es": "Ruinas en lo alto de una colina de un palacio del siglo V a. C. con vistas al mar cerca de Lefke, que combinan estilos arquitectónicos persa y griego. Sus terrazas y cisternas aún trazan el plano del complejo real.", "de": "Die Ruinen eines Palastes aus dem 5. Jahrhundert v. Chr. auf einem Hügel über dem Meer nahe Lefke, in dem sich persische und griechische Baustile verbinden. Terrassen und Zisternen lassen den Grundriss der königlichen Anlage noch heute erkennen.", "fa": "ویرانه‌های کاخی بر فراز تپه از قرن پنجم پیش از میلاد، مشرف به دریا در نزدیکی لفکه، که سبک‌های معماری ایرانی و یونانی را درهم می‌آمیزد. مهتابی‌ها و آب‌انبارهایش هنوز نقشه این مجموعه سلطنتی را نشان می‌دهند."}'::jsonb),  -- Vouni Palace
  ('328fad9c-9da7-4273-a638-1682de89da39'::uuid, '07482d4d1543f46c920dcf5c064b6608', '{"ar": "بقايا مدينة مملكة قديمة على خليج مورفو، تضم مسرحًا رومانيًا وبازيليكا مسيحية مبكرة تحتفظ بأرضيات فسيفسائية رائعة، من بينها فسيفساء البجعة الشهيرة.", "ru": "Руины древнего города-царства на берегу залива Морфу с римским театром и раннехристианской базиликой, где сохранились прекрасные мозаичные полы, в том числе знаменитая мозаика с лебедем.", "el": "Τα ερείπια μιας αρχαίας πόλης-βασιλείου στον κόλπο της Μόρφου, με ρωμαϊκό θέατρο και παλαιοχριστιανική βασιλική που διατηρεί εξαιρετικά ψηφιδωτά δάπεδα, ανάμεσά τους και το περίφημο ψηφιδωτό του κύκνου.", "fr": "Vestiges d''une ancienne cité-royaume sur la baie de Morphou, avec un théâtre romain et une basilique paléochrétienne aux beaux pavements de mosaïques, dont une célèbre mosaïque au cygne.", "es": "Restos de una antigua ciudad-reino en la bahía de Morphou, con un teatro romano y una basílica paleocristiana que conserva bellos suelos de mosaico, entre ellos un célebre mosaico del cisne.", "de": "Die Überreste eines antiken Stadtkönigreichs an der Bucht von Morphou, mit einem römischen Theater und einer frühchristlichen Basilika, deren feine Mosaikböden erhalten sind, darunter ein berühmtes Schwanenmosaik.", "fa": "بقایای یک دولت‌شهر پادشاهی باستانی در خلیج مورفو، با تئاتری رومی و باسیلیکایی مسیحی اولیه که کف‌پوش‌های موزاییکی زیبایی را حفظ کرده است، از جمله موزاییک مشهور قو."}'::jsonb),  -- Soli Ruins
  ('6169028b-2497-4d86-8ed1-7b4598af0122'::uuid, '78b67759147439c6033ad2b3a060240f', '{"ar": "متحف في محطة غوزيليورت السابقة يستحضر سكة حديد حكومة قبرص التي كانت تعبر الجزيرة حتى عام 1951، ويضم عربات قطارات وقطعًا من مقتنيات السكك الحديدية.", "ru": "Музей в здании бывшей станции Гюзельюрт, напоминающий о Кипрской государственной железной дороге, которая пересекала остров до 1951 года; здесь представлены подвижной состав и железнодорожные артефакты.", "el": "Μουσείο στον πρώην σταθμό του Güzelyurt (Μόρφου) που θυμίζει τον Κυβερνητικό Σιδηρόδρομο της Κύπρου, ο οποίος διέσχιζε το νησί έως το 1951, με τροχαίο υλικό και σιδηροδρομικά αντικείμενα.", "fr": "Musée installé dans l''ancienne gare de Güzelyurt, évoquant le Cyprus Government Railway, qui traversa l''île jusqu''en 1951, avec du matériel roulant et des objets ferroviaires.", "es": "Museo en la antigua estación de Güzelyurt que recuerda el Cyprus Government Railway, el ferrocarril que recorrió la isla hasta 1951, con material rodante y objetos ferroviarios.", "de": "Ein Museum im ehemaligen Bahnhof von Güzelyurt, das an die Cyprus Government Railway erinnert, die bis 1951 quer über die Insel fuhr, mit Rollmaterial und Eisenbahn-Exponaten.", "fa": "موزه‌ای در ایستگاه سابق گوزل‌یورت که یادآور راه‌آهن دولتی قبرس است که تا سال ۱۹۵۱ در سراسر جزیره فعالیت می‌کرد، با واگن‌ها و اشیای مرتبط با راه‌آهن."}'::jsonb),  -- Güzelyurt Railway Station Museum
  ('7edf6c7d-9bd2-4617-afdc-af1a3443d3e6'::uuid, '901e26b2257d6a91757a4fca65ecc4d2', '{"ar": "متحف في ليفكه يقع في مبنى «واصف بالاس» التاريخي، ويوثّق تاريخ تعدين النحاس والبيريت في المنطقة الذي شكّل الاقتصاد المحلي.", "ru": "Музей в Лефке, размещённый в историческом здании Васыф Палас и рассказывающий об истории добычи меди и пирита, определившей экономику региона.", "el": "Μουσείο στο Lefke (Λεύκα), στεγασμένο στο ιστορικό κτίριο Vasıf Palas, που τεκμηριώνει την ιστορία της εξόρυξης χαλκού και σιδηροπυρίτη, η οποία διαμόρφωσε την τοπική οικονομία.", "fr": "Musée de Lefke installé dans le bâtiment historique du Vasıf Palas, retraçant l''histoire de l''extraction du cuivre et de la pyrite qui a façonné l''économie locale.", "es": "Museo en Lefke instalado en el histórico edificio Vasıf Palas, que documenta la historia de la minería del cobre y la pirita que marcó la economía local.", "de": "Ein Museum in Lefke im historischen Gebäude Vasıf Palas, das die Geschichte des Kupfer- und Pyritbergbaus der Region dokumentiert, der die lokale Wirtschaft prägte.", "fa": "موزه‌ای در لفکه در بنای تاریخی واصف پالاس که تاریخ استخراج مس و پیریت منطقه را که اقتصاد محلی را شکل داد، مستند می‌کند."}'::jsonb)  -- Lefke Mining Museum
  ) AS v(id, en_md5, add)
 WHERE p.id = v.id AND md5(p.description_i18n->>'en') = v.en_md5;

DO $$
DECLARE v_bad text;
BEGIN
  -- End state: every one of the 33 holds exactly the nine languages, all non-empty, and the
  -- corrected wording is in place.
  SELECT string_agg(name, ', ') INTO v_bad FROM public.places
   WHERE official_visit IS NOT NULL
     AND (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(description_i18n) k)
         IS DISTINCT FROM ARRAY['ar','de','el','en','es','fa','fr','ru','tr']
      OR (official_visit IS NOT NULL AND EXISTS (
           SELECT 1 FROM jsonb_each_text(description_i18n) e WHERE length(trim(e.value)) = 0));
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'descriptions incomplete on: %', v_bad; END IF;
  IF (SELECT count(*) FROM public.places WHERE official_visit IS NOT NULL) IS DISTINCT FROM 33 THEN
    RAISE EXCEPTION 'expected the 33 places of 20261155 — is it applied?';
  END IF;
  IF EXISTS (SELECT 1 FROM public.places WHERE official_visit IS NOT NULL AND (
       description_i18n->>'en' ILIKE '%amphitheatre%' OR description_i18n->>'en' LIKE '%2,400-year-old%'
       OR description_i18n->>'en' LIKE '%late-18th-century%')) THEN
    RAISE EXCEPTION 'a corrected description still carries the old wording (Salamis Ancient City, Kyrenia Castle, Dervish Pasha Mansion)';
  END IF;
END $$;
